POLICIES.forEach(p => { p.path = `/${p.slug}/`; });

// Escaped text with email addresses and the site address turned into links.
const text = s => esc(s)
  .replace(/[\w.+-]+@[\w-]+\.[\w.]+\w/g, m => `<a href="mailto:${m}">${m}</a>`)
  .replace(/https:\/\/vintorex\.com\//g, m => `<a href="${m}">${m}</a>`);

const block = ([kind, value]) => ({
  h2: () => `<h2>${text(value)}</h2>`,
  p: () => `<p>${text(value)}</p>`,
  strong: () => `<p><strong>${text(value)}</strong></p>`,
  ul: () => `<ul>${value.map(v => `<li>${text(v)}</li>`).join('')}</ul>`,
  ol: () => `<ol>${value.map(v => `<li>${text(v)}</li>`).join('')}</ol>`,
  dl: () => `<dl class="kv">${value.map(([k, v]) => `<div><dt>${esc(k)}</dt><dd>${text(v)}</dd></div>`).join('')}</dl>`,
})[kind]();

// Page body for one policy, with links to the others.
export const policyHtml = p => `<article class="shell section narrow policy">
      <nav class="chips" aria-label="Policies">${POLICIES.map(x => `<a class="chip ${x === p ? 'on' : ''}" href="${x.path}" ${x === p ? 'aria-current="page"' : ''}>${esc(x.label)}</a>`).join('')}</nav>
      <h1>${esc(p.title)}</h1>
      <p class="muted">Last updated ${POLICIES_UPDATED}</p>
      <div class="prose-article">${p.body.map(block).join('\n')}</div>
    </article>`;
